// GC-4：跳过防御性拷贝的 internal 构造。调用方（如 RtcMsgPackReader）已持有
// 独占数组，无需再复制一份。仅 SDK 内部使用（internal），不对外暴露。
internal static RtcValue OfArrayDirect(RtcValue[] ownedItems)
{
    return ownedItems.Length == 0
        ? EmptyArray
        : new RtcValue(RtcValueKind.Array) { ArrayValue = ownedItems };
}

// The caller transfers ownership of ownedFields to the returned value.
// The array must not be modified or reused after this call.
public static RtcValue OfMapDirect(RtcField[] ownedFields)
{
    if (ownedFields == null)
    {
        throw new ArgumentNullException(nameof(ownedFields));
    }

    return ownedFields.Length == 0
        ? EmptyMap
        : new RtcValue(RtcValueKind.Map) { MapValue = ownedFields };
}

